CREATE TABLE IF NOT EXISTS chat_presence (user_type ENUM('citizen','admin') NOT NULL, user_id INT UNSIGNED NOT NULL, last_seen DATETIME NOT NULL, PRIMARY KEY(user_type,user_id), KEY last_seen(last_seen)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS chat_conversations (id INT UNSIGNED NOT NULL AUTO_INCREMENT, citizen_id INT UNSIGNED NOT NULL, assigned_admin_id INT UNSIGNED NULL, last_message_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(id), UNIQUE KEY citizen_id(citizen_id), KEY assigned_admin_id(assigned_admin_id), KEY last_message_at(last_message_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS chat_messages (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, conversation_id INT UNSIGNED NOT NULL, sender_type ENUM('citizen','admin') NOT NULL, sender_id INT UNSIGNED NOT NULL, message TEXT NOT NULL, is_read TINYINT(1) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(id), KEY conversation_messages(conversation_id,id), KEY unread_lookup(conversation_id,sender_type,is_read)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
